begin;
set local role riuya_purge_executor;
grant execute on function private.purge_account_contributions(uuid,uuid),private.purge_editorial_references(uuid,uuid) to postgres;
reset role;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();jid uuid:=gen_random_uuid();tok uuid:=gen_random_uuid();
 cat uuid:=gen_random_uuid();lab uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();rev1 uuid:=gen_random_uuid();rev2 uuid:=gen_random_uuid();op1 uuid:=gen_random_uuid();op2 uuid:=gen_random_uuid();src uuid:=gen_random_uuid();ev uuid:=gen_random_uuid();character uuid;category uuid;item1 uuid:=gen_random_uuid();item2 uuid:=gen_random_uuid();groupid uuid:=gen_random_uuid();
begin
 if has_function_privilege('authenticated','private.purge_editorial_references(uuid,uuid)','execute') or has_function_privilege('riuya_worker_local','private.purge_editorial_references(uuid,uuid)','execute') then raise exception 'EXPOSED';end if;
 insert into auth.users(id,email) values(u,'z11-ed-'||u||'@example.invalid'),(v,'z11-ed-'||v||'@example.invalid');
 insert into private.profiles(id,account_status) values(u,'deletion_pending'),(v,'active');
 select id into category from private.categories limit 1;select id into character from private.characters limit 1;
 insert into private.aspect_catalogs(id,version,status) values(cat,'z11-'||cat,'proposed');
 insert into private.aspect_labels(id,catalog_id,dimension,label_key,definition,positive_examples,negative_examples) values(lab,cat,'emotion','fixture','fixture','["a"]','["b"]');
 update private.aspect_catalogs set status='validated',validated_at=now(),validated_by=u where id=cat;
 insert into private.articles(id,category_id,created_by,approved_by) values(a,category,u,u),(b,category,v,null);
 insert into private.article_revisions(id,article_id,revision_number,title,micro_summary,full_paragraphs,created_by) values(rev1,a,1,'A','A','[]',u),(rev2,b,1,'B','B','[]',u);
 insert into private.opinions(id,revision_id,character_id,body) values(op1,rev1,character,'A'),(op2,rev2,character,'B');
 insert into private.opinion_aspects(opinion_id,label_id,dimension,weight_basis_points,evidence,reviewed_by,second_reviewed_by) values(op1,lab,'emotion',10000,'prueba',u,v),(op2,lab,'emotion',10000,'prueba',v,u);
 insert into private.aspect_annotation_proposals(opinion_id,dimension,reviewer_id,proposal) values(op1,'emotion',u,'[]'),(op2,'emotion',v,'[]');
 update private.articles set status='published',published_at=now(),current_revision_id=rev1 where id=a;
 update private.articles set status='review',current_revision_id=rev2 where id=b;
 insert into private.editorial_events(id,article_id,event_type,actor_id) values(ev,a,'publish',u);
 insert into private.sources(id,name,domain,source_type,base_url,verified,verified_by) values(src,'z11','example.invalid','rss','https://example.invalid',true,u);
 insert into private.source_items(id,source_id,canonical_url,title,external_date) values(item1,src,'https://example.invalid/'||item1,'A',now()),(item2,src,'https://example.invalid/'||item2,'B',now());
 insert into private.source_group_proposals(id,item_a,item_b,status,decided_by,decided_at) values(groupid,least(item1,item2),greatest(item1,item2),'rejected',u,now());
 perform set_config('riuya.purge_actor',u::text,true);
 begin update private.opinion_aspects set reviewed_by=v,second_reviewed_by=null where opinion_id=op1;raise exception 'GUARD_BYPASSED'; exception when raise_exception then if sqlerrm<>'ASPECT_REVISION_LOCKED' then raise;end if;end;
 perform set_config('riuya.purge_actor','',true);
 insert into private.account_deletion_requests(id,user_id,requested_at,recover_until,status) values(rid,u,now()-interval '8 days',now()-interval '1 day','pending');
 insert into private.jobs(id,job_type,payload,dedupe_key,created_by,status,locked_by,lease_token,lease_until) values(jid,'account.purge',jsonb_build_object('requestId',rid),'z11-ed-'||jid,u,'running','fixture',tok,now()+interval '1 hour');
 perform private.purge_account_contributions(jid,tok);
 perform private.purge_editorial_references(jid,tok);
 perform private.purge_editorial_references(jid,tok);
 if exists(select 1 from private.opinion_aspects where (opinion_id=op1 or opinion_id=op2) and (reviewed_by is distinct from v or second_reviewed_by is not null)) then raise exception 'OTHER_REVIEWER_LOST';end if;
 if exists(select 1 from private.aspect_annotation_proposals where reviewer_id=u) or not exists(select 1 from private.aspect_annotation_proposals where reviewer_id=v and opinion_id=op2) then raise exception 'PROPOSAL_SCOPE';end if;
 if not exists(select 1 from private.aspect_catalogs where id=cat and status='retired' and validated_by is null and validator_deleted) then raise exception 'CATALOG';end if;
 if not exists(select 1 from private.articles where id=a and status='published' and created_by is null and approved_by is null) or not exists(select 1 from private.articles where id=b and status='draft' and created_by=v and version=2) then raise exception 'ARTICLE_STATE';end if;
 if exists(select 1 from private.article_revisions where id in (rev1,rev2) and created_by is not null) or exists(select 1 from private.editorial_events where id=ev and actor_id is not null) then raise exception 'EDITOR_ID';end if;
 if not exists(select 1 from private.source_group_proposals where id=groupid and status='rejected' and decided_by is null and decision_actor_deleted and decided_at is not null) then raise exception 'GROUP_DECISION';end if;
 if not exists(select 1 from private.sources where id=src and not verified and verified_by is null and version=2) then raise exception 'SOURCE';end if;
end $$;
set local role authenticated;
set constraints all immediate;
reset role;
rollback;
